]

# Apply transform to demo
def flood_fill_from_bg(grid, bg=0):
    rows = len(grid)
    cols = len(grid[0])
    visited = [[False]*cols for _ in range(rows)]
    queue = []

    for r in range(rows):
        for c in [0, cols-1]:
            if grid[r][c] == bg and not visited[r][c]:
                queue.append((r, c))
                visited[r][c] = True
        if r < rows and grid[r][c] == bg and not visited[r][c]:
            queue.append((r, c))
            visited[r][c] = True

    for c in range(cols):
        for r in [0, rows-1]:
            if grid[r][c] == bg and not visited[r][c]:
                queue.append((r, c))
                visited[r][c] = True

    while queue:
        r, c = queue.pop(0)
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] == bg and not visited[nr][nc]:
                    visited[nr][nc] = True
                    queue.append((nr, nc))

    return visited

result = []
for r in range(len(demo_transform)):
    row = demo_transform[r][:]
    for c in range(len(demo_transform[0])):
        if demo_transform[r][c] == 0 and not flood_fill_from_bg(demo_transform)[r][c]:
            row[c] = 4
    result.append(row)

print("Demo result matches expected?", result == demo_expected)

# If mismatch, find differences
if result != demo_expected:
